('<lesson_id>', 'order', replace($blk${"words": ["Did", "they", "arrive", "at", "the", "station", "on", "time?"], "sentence": "Did they arrive at the station on time?", "audio_tts": "Did they arrive at the station on time?"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 18),
('<lesson_id>', 'order', replace($blk${"words": ["We", "didn't", "get", "off", "the", "train."], "sentence": "We didn't get off the train.", "audio_tts": "We didn't get off the train."}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 19),
