('<lesson_id>', 'task', replace($blk${"title": "Моя дорога в школу ✍️", "html": "<p>Дополнительное задание для самых смелых! Расскажи, как ты добираешься до школы. Постарайся ответить на вопросы:</p><ul><li>What time do you leave home?</li><li>What transport do you use?</li><li>How long does it take?</li><li>Do you like your journey to school? Why/Why not?</li></ul><p>Не забудь прочитать свой рассказ учителю!</p>", "needs_review": true}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 21),
('<lesson_id>', 'text', replace($blk${"html": "<p><img src=\"@@MEDIA@@shared/well_done_star.webp\" alt=\"\" style=\"height:200px\"></p><h2>Ты супер ученик! ⭐</h2><p>Ты справился с домашним заданием — держи звёздочку! До встречи на занятии!</p>"}$blk$, '@@MEDIA@@', 'https://classroom.wowteach.ru/media/')::jsonb, 22)
